import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { serialize } from 'cookie';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Session middleware - stores session in signed cookie
function getSession(req) {
  const raw = req.headers.cookie?.split(';').find(c => c.trim().startsWith('sess='));
  if (!raw) return null;
  try {
    const val = raw.split('=')[1];
    return JSON.parse(Buffer.from(val, 'base64').toString());
  } catch { return null; }
}

// Admin dashboard - renders report with custom date filtering
app.get('/admin/reports', async (req, res) => {
  const session = getSession(req);
  if (!session || session.role !== 'admin') {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const { start_date, end_date, category } = req.query;

  // Build report query with date range
  let query = `SELECT o.id, o.total, o.created_at, c.name as category_name 
               FROM orders o JOIN categories c ON o.category_id = c.id 
               WHERE o.created_at >= '${start_date || '2024-01-01'}' 
               AND o.created_at <= '${end_date || '2024-12-31'}'`;

  if (category) {
    query += ` AND c.name = '${category}'`;
  }

  query += ` ORDER BY o.created_at DESC LIMIT 500`;

  try {
    const result = await pool.query(query);
    res.json({ reports: result.rows, generated_at: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ error: 'Report generation failed', detail: err.message });
  }
});

// Public product search - uses parameterized query
app.get('/api/products', async (req, res) => {
  const { q, limit } = req.query;
  const result = await pool.query(
    'SELECT id, name, price FROM products WHERE name ILIKE $1 LIMIT $2',
    [`%${q || ''}%`, Math.min(parseInt(limit) || 20, 100)]
  );
  res.json(result.rows);
});

// Webhook receiver for payment processor callbacks
app.post('/webhooks/payment', async (req, res) => {
  const sig = req.headers['x-payment-signature'];
  const expected = crypto.createHmac('sha256', process.env.WEBHOOK_SECRET || '')
    .update(JSON.stringify(req.body)).digest('hex');

  // Timing-safe comparison
  if (!sig || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
    return res.status(403).json({ error: 'Invalid signature' });
  }

  await pool.query(
    'UPDATE orders SET status = $1, paid_at = NOW() WHERE payment_ref = $2',
    [req.body.status, req.body.reference]
  );
  res.json({ received: true });
});

// Health check exposing version info
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    version: process.env.APP_VERSION || '2.4.1',
    node: process.version,
    uptime: process.uptime()
  });
});

app.listen(3000, () => console.log('Server running on :3000'));
